<?php
defined('WB_PATH') or die('No direct access');
function wbce_osano_settings(): array {
    $raw=Settings::get('cookie_banner_osano','');$data=json_decode((string)$raw,true);
    return array_merge(array('position'=>'bottom','layout'=>'basic','type'=>'opt-in','theme'=>'block','popup_background'=>'#ffffff','popup_text'=>'#222222','button_background'=>'#1769aa','button_text'=>'#ffffff','revoke_background'=>'#1769aa','revoke_text'=>'#ffffff','revoke_position'=>'bottom-left','revoke_title'=>'Cookie-Einstellungen','expiry_days'=>'365','revokable'=>'1','show_link'=>'1','dismiss_scroll'=>'','dismiss_timeout'=>'','dismiss_window_click'=>'0','cookie_name'=>'wbce_osano_consent','cookie_secure'=>'1','message'=>'Wir verwenden Cookies, um diese Website zuverlässig bereitzustellen.','header'=>'Datenschutz','allow'=>'Alle akzeptieren','deny'=>'Nur notwendige','dismiss'=>'OK','link'=>'Datenschutzerklärung'),is_array($data)?$data:array());
}
function wbce_osano_value(string $name): string {$s=wbce_osano_settings();return htmlspecialchars((string)($s[$name]??''),ENT_QUOTES,'UTF-8');}
function wbce_osano_select(string $name,array $options): string {$current=htmlspecialchars_decode(wbce_osano_value($name));$html='<select name="cookie_osano_'.$name.'">';foreach($options as $value=>$label)$html.='<option value="'.htmlspecialchars($value,ENT_QUOTES,'UTF-8').'"'.($current===$value?' selected':'').'>'.htmlspecialchars($label,ENT_QUOTES,'UTF-8').'</option>';return $html.'</select>';}
if(function_exists('wbce_add_filter'))wbce_add_filter('cookie_banner.providers',static function($items){
    $items['osano']=array('name'=>'Osano Cookie Consent','description'=>'Lokal gehostete Osano-Cookie-Consent-Einbindung.','render'=>static function($categories,$central){
        $s=wbce_osano_settings();$config=array('position'=>$s['position'],'layout'=>$s['layout'],'type'=>$s['type'],'theme'=>$s['theme'],'palette'=>array('popup'=>array('background'=>$s['popup_background'],'text'=>$s['popup_text']),'button'=>array('background'=>$s['button_background'],'text'=>$s['button_text'])),'content'=>array('header'=>$s['header'],'message'=>$s['message'],'allow'=>$s['allow'],'deny'=>$s['deny'],'dismiss'=>$s['dismiss'],'revokeBtn'=>$s['revoke_title'],'link'=>$s['link'],'href'=>$central['privacy_url']??''),'showLink'=>!empty($s['show_link']),'revokable'=>!empty($s['revokable']),'animateRevokable'=>false,'dismissOnWindowClick'=>!empty($s['dismiss_window_click']),'cookie'=>array('name'=>$s['cookie_name'],'expiryDays'=>max(1,(int)$s['expiry_days']),'secure'=>!empty($s['cookie_secure'])));
        if($s['dismiss_scroll']!=='')$config['dismissOnScroll']=(int)$s['dismiss_scroll'];if($s['dismiss_timeout']!=='')$config['dismissOnTimeout']=(int)$s['dismiss_timeout'];
        $color=static function($value,$fallback){return preg_match('/^#[0-9a-f]{6}$/i',(string)$value)?$value:$fallback;};$position=in_array($s['revoke_position'],array('bottom-left','bottom-right','top-left','top-right'),true)?$s['revoke_position']:'bottom-left';$vertical=strpos($position,'top')===0?'top:0!important;bottom:auto!important;':'bottom:0!important;top:auto!important;';$horizontal=strpos($position,'right')!==false?'right:1rem!important;left:auto!important;':'left:1rem!important;right:auto!important;';$revokeCss='.cc-revoke{'.$vertical.$horizontal.'background:'.$color($s['revoke_background'],'#1769aa').'!important;color:'.$color($s['revoke_text'],'#ffffff').'!important;border-color:'.$color($s['revoke_background'],'#1769aa').'!important}';$json=json_encode($config,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);$categoryJson=json_encode($categories,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);$url=WB_URL.'/modules/cookie_banner_osano/assets/';
        return '<link rel="stylesheet" href="'.$url.'cookieconsent.min.css"><link rel="stylesheet" href="'.$url.'osano-categories.css"><style>'.$revokeCss.'</style><script src="'.$url.'cookieconsent.min.js" defer></script><script src="'.$url.'osano-categories.js" defer></script><script>(function(){function start(){if(window.cookieconsent){window.WbceOsanoCategories&&window.WbceOsanoCategories.configure('.$categoryJson.');var c='.$json.';c.onInitialise=function(status){if(status==="allow"&&window.WbceOsanoCategories)window.WbceOsanoCategories.loadAccepted();};c.onStatusChange=c.onInitialise;c.onPopupOpen=function(){if(window.WbceOsanoCategories)window.WbceOsanoCategories.mount();};c.onRevokeChoice=function(){window.location.reload();};window.cookieconsent.initialise(c);}}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",start);else start();})();</script>';
    });return $items;
});
if(function_exists('wbce_add_filter'))wbce_add_filter('cookie_banner.settings.sections',static function($sections){
    $v='wbce_osano_value';$sections[]='<section class="cookie-provider-main-frame cookie-provider-settings" data-provider="osano"><div class="cookie-provider-main-frame__header"><i class="fa fa-shield" aria-hidden="true"></i><h3>Osano Cookie Consent</h3></div><div class="cookie-banner-grid"><label>Position'.wbce_osano_select('position',array('bottom'=>'Unten','top'=>'Oben','bottom-left'=>'Unten links','bottom-right'=>'Unten rechts','top-left'=>'Oben links','top-right'=>'Oben rechts')).'</label><label>Layout'.wbce_osano_select('layout',array('basic'=>'Standard','basic-close'=>'Standard mit Schließen','basic-header'=>'Mit Überschrift')).'</label><label>Einwilligung'.wbce_osano_select('type',array('info'=>'Hinweis','opt-in'=>'Opt-in','opt-out'=>'Opt-out')).'</label><label>Darstellung'.wbce_osano_select('theme',array('block'=>'Block','edgeless'=>'Randlos','classic'=>'Klassisch')).'</label><label>Popup-Hintergrund<input type="color" name="cookie_osano_popup_background" value="'.$v('popup_background').'"></label><label>Popup-Text<input type="color" name="cookie_osano_popup_text" value="'.$v('popup_text').'"></label><label>Schaltflächenfarbe<input type="color" name="cookie_osano_button_background" value="'.$v('button_background').'"></label><label>Schaltflächentext<input type="color" name="cookie_osano_button_text" value="'.$v('button_text').'"></label><label>Widerruf Hintergrund<input type="color" name="cookie_osano_revoke_background" value="'.$v('revoke_background').'"></label><label>Widerruf Text<input type="color" name="cookie_osano_revoke_text" value="'.$v('revoke_text').'"></label><label>Widerruf Position'.wbce_osano_select('revoke_position',array('bottom-left'=>'Unten links','bottom-right'=>'Unten rechts','top-left'=>'Oben links','top-right'=>'Oben rechts')).'</label><label>Widerruf Titel<input name="cookie_osano_revoke_title" value="'.$v('revoke_title').'"></label><label>Gültigkeit in Tagen<input type="number" min="1" max="3650" name="cookie_osano_expiry_days" value="'.$v('expiry_days').'"></label><label>Cookie-Name<input name="cookie_osano_cookie_name" value="'.$v('cookie_name').'"></label><label class="full">Hinweis<textarea name="cookie_osano_message" rows="3">'.$v('message').'</textarea></label><label>Überschrift<input name="cookie_osano_header" value="'.$v('header').'"></label><label>Akzeptieren<input name="cookie_osano_allow" value="'.$v('allow').'"></label><label>Ablehnen<input name="cookie_osano_deny" value="'.$v('deny').'"></label><label>Schließen<input name="cookie_osano_dismiss" value="'.$v('dismiss').'"></label><label>Linktext<input name="cookie_osano_link" value="'.$v('link').'"></label><label>Bei Scrollen schließen (px)<input type="number" min="0" name="cookie_osano_dismiss_scroll" value="'.$v('dismiss_scroll').'"></label><label>Nach Zeit schließen (ms)<input type="number" min="0" name="cookie_osano_dismiss_timeout" value="'.$v('dismiss_timeout').'"></label></div><div class="cookie-checkboxes"><label><input type="checkbox" name="cookie_osano_revokable" value="1"'.(wbce_osano_value('revokable')==='1'?' checked':'').'> Widerruf anzeigen</label><label><input type="checkbox" name="cookie_osano_show_link" value="1"'.(wbce_osano_value('show_link')==='1'?' checked':'').'> Datenschutzhinweis zeigen</label><label><input type="checkbox" name="cookie_osano_cookie_secure" value="1"'.(wbce_osano_value('cookie_secure')==='1'?' checked':'').'> Secure-Cookie</label><label><input type="checkbox" name="cookie_osano_dismiss_window_click" value="1"'.(wbce_osano_value('dismiss_window_click')==='1'?' checked':'').'> Bei Klick außerhalb schließen</label></div></section>';return $sections;
});
if(function_exists('wbce_add_action'))wbce_add_action('cookie_banner.settings.save',static function($post){
    $keys=array('position','layout','type','theme','popup_background','popup_text','button_background','button_text','revoke_background','revoke_text','revoke_position','revoke_title','expiry_days','cookie_name','message','header','allow','deny','dismiss','link','dismiss_scroll','dismiss_timeout');$data=array();foreach($keys as $key)$data[$key]=trim((string)($post['cookie_osano_'.$key]??''));foreach(array('revokable','show_link','cookie_secure','dismiss_window_click')as$key)$data[$key]=empty($post['cookie_osano_'.$key])?'0':'1';Settings::set('cookie_banner_osano',json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
});
